import java.util.*;

public class MinCostFlow {
    static class Edge {
        int y, c, f, cost;
        Edge(int y, int c, int f, int cost) {
            this.y = y;
            this.c = c;
            this.f = f;
            this.cost = cost;
        }
    }

    static List<Edge> edges = new ArrayList<>();
    static List<Integer>[] graph;
    static long totalCost = 0;
    static long[] dist;
    static int[] parent, parentEdge, inQueue;
    static final long INF = (long)1e18;
    static int source, sink;

    static int remainingCapacity(int x) {
        return edges.get(x).c - edges.get(x).f;
    }

    static void augmentFlow() {
        int n = graph.length;
        Arrays.fill(dist, INF);
        Arrays.fill(parent, -1);
        Arrays.fill(parentEdge, -1);
        Arrays.fill(inQueue, 0);
        dist[source] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.offer(source);
        inQueue[source] = 1;
        while (!q.isEmpty()) {
            int node = q.poll();
            inQueue[node] = 0;
            for (int edgeIdx : graph[node]) {
                if (remainingCapacity(edgeIdx) == 0) continue;
                int costC = edges.get(edgeIdx).cost;
                int neighbor = edges.get(edgeIdx).y;
                if (dist[neighbor] > dist[node] + costC) {
                    dist[neighbor] = dist[node] + costC;
                    parent[neighbor] = node;
                    parentEdge[neighbor] = edgeIdx;
                    if (inQueue[neighbor] == 0) {
                        inQueue[neighbor] = 1;
                        q.offer(neighbor);
                    }
                }
            }
        }
        int current = sink;
        while (current != source) {
            int eIdx = parentEdge[current];
            edges.get(eIdx).f++;
            edges.get(eIdx ^ 1).f--;
            current = parent[current];
        }
        totalCost += dist[sink];
    }

    static void createEdge(int from, int to, int capacity, int cost) {
        graph[from].add(edges.size());
        edges.add(new Edge(to, capacity, 0, cost));
        graph[to].add(edges.size());
        edges.add(new Edge(from, 0, 0, -cost));
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int k = sc.nextInt();
        int c = sc.nextInt();
        int d = sc.nextInt();

        int MAXN = 14043;
        graph = new ArrayList[MAXN];
        for (int i = 0; i < MAXN; i++) {
            graph[i] = new ArrayList<>();
        }
        dist = new long[MAXN];
        parent = new int[MAXN];
        parentEdge = new int[MAXN];
        inQueue = new int[MAXN];

        source = MAXN - 2;
        sink = MAXN - 1;

        for (int i = 0; i < k; i++) {
            int x = sc.nextInt();
            createEdge(source, x, 1, 0);
        }

        int tt = 101;
        for (int i = 0; i < tt; i++) {
            createEdge(1 + i * n, sink, k, i * c);
        }

        for (int i = 0; i < m; i++) {
            int x = sc.nextInt();
            int y = sc.nextInt();
            for (int j = 0; j < tt - 1; j++) {
                createEdge(x + j * n, y + j * n + n, 1, d * (j * 2 + 1));
                createEdge(y + j * n, x + j * n + n, 1, d * (j * 2 + 1));
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < tt - 1; j++) {
                createEdge(i + j * n, i + j * n + n, k, 0);
            }
        }

        for (int i = 0; i < k; i++) {
            augmentFlow();
        }

        System.out.println(totalCost);
        sc.close();
    }
}
